import {createHash} from 'node:crypto';
import {HttpError} from '../http-error';
import {hasPerm} from '../perms-shared';
import {normalizeFa,normalizeFaWithMap,chatPreview,REACTION_SET,DEFAULT_ALLOWED_EXT,BLOCKED_EXT,fileExt,type ChatMessage} from '../chat-shared';
