 async members(scope:ChatScope,id:number){const presence=hasPerm(scope.permissions,'chat.presence'),rows=(await this.db.query(`SELECT m.*,u.name,u.role user_role,u.avatar_color,p.last_seen_at FROM ${this.q('chat_members')} m JOIN ${this.q('users')} u ON u.id=m.user_id LEFT JOIN ${this.q('chat_presence')} p ON p.user_id=u.id WHERE m.conversation_id=$1 AND m.left_at IS NULL ORDER BY CASE m.role WHEN 'owner' THEN 0 WHEN 'admin' THEN 1 ELSE 2 END,m.joined_at,u.id LIMIT 102`,[id])).rows;return rows.map(r=>({user_id:integer(r.user_id),name:String(r.name),role:String(r.user_role),conv_role:String(r.role),avatar_color:String(r.avatar_color??'#0ea5e9'),joined_at:String(r.joined_at),last_read_message_id:integer(r.last_read_message_id),online:presence?millis(r.last_seen_at)>Date.now()-70000:undefined,last_seen_at:presence?r.last_seen_at??null:undefined}));}
